{
  "findings": [
    {
      "check_id": "CKV_AWS_355",
      "title": "Overly broad S3 read access",
      "resource": "aws_iam_policy_attachment.pass4",
      "severity": "HIGH",
      "explanation": "The AWS-managed AmazonS3ReadOnlyAccess policy grants the role read and list permissions across all S3 resources in the account. If the role is compromised, an attacker could access sensitive data from unrelated buckets."
    }
  ],
  "patched_code": "variable "s3_read_bucket_arn" {
  description = "ARN of the S3 bucket that the role is permitted to read"
  type        = string
}

resource "aws_iam_policy" "pass4" {
  name_prefix = "s3-read-only-"
  description = "Read-only access to the specified S3 bucket"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ReadBucket"
        Effect = "Allow"
        Action = [
          "s3:GetBucketLocation",
          "s3:ListBucket"
        ]
        Resource = var.s3_read_bucket_arn
      },
      {
        Sid    = "ReadObjects"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion"
        ]
        Resource = "${var.s3_read_bucket_arn}/*"
      }
    ]
  })
}

resource "aws_iam_policy_attachment" "pass4" {
  name       = "policy"
  roles      = [aws_iam_role.pass1.name]
  policy_arn = aws_iam_policy.pass4.arn
}
",
  "fix_summary": "Replaced the account-wide AWS-managed S3 policy with a customer-managed policy scoped to an explicitly supplied bucket ARN. Also corrected the attachment to use the valid `roles` argument."
}
